alter table public.websites add column if not exists description_checked_at timestamptz;
comment on column public.websites.description_checked_at is 'When a description sweep last read this homepage, whatever the outcome. Null means never. Stops one sweep re-fetching the domains that yielded nothing.';
create index if not exists websites_description_sweep_idx on public.websites (description_checked_at nulls first) where status <> 'archived';
create table if not exists public.description_runs ( id uuid primary key default gen_random_uuid(), status text not null default 'running' check (status in ('running', 'finished', 'cancelled', 'failed')), total integer not null default 0, looked integer not null default 0, filled integer not null default 0, nothing_useful integer not null default 0, failed integer not null default 0, first_error text, ticks integer not null default 0, claimed_at timestamptz, started_at timestamptz not null default timezone('utc', now()), finished_at timestamptz, started_by text );
create index if not exists description_runs_started_idx on public.description_runs (started_at desc);
create unique index if not exists description_runs_one_running_idx on public.description_runs ((true)) where status = 'running';
create or replace function public.claim_description_run(p_stale_seconds integer default 600) returns uuid language plpgsql volatile security definer set search_path = public as $$ declare v_id uuid; begin update public.description_runs r set claimed_at = timezone('utc', now()), ticks = r.ticks + 1 where r.id = ( select c.id from public.description_runs c where c.status = 'running' and ( c.claimed_at is null or c.claimed_at < timezone('utc', now()) - make_interval(secs => greatest(60, p_stale_seconds)) ) order by c.started_at for update skip locked limit 1 ) returning r.id into v_id; return v_id; end; $$;
create or replace function public.description_sweep_batch( p_since timestamptz, p_limit integer default 40 ) returns table (id uuid, domain text) language sql stable security definer set search_path = public as $$ select w.id, w.domain from public.websites w where w.status <> 'archived' and (w.description is null or w.description = '') and (w.description_checked_at is null or w.description_checked_at < p_since) order by w.description_checked_at asc nulls first, w.id asc limit greatest(1, least(500, p_limit)); $$;
revoke all on function public.description_sweep_batch(timestamptz, integer) from public;
revoke all on function public.description_sweep_batch(timestamptz, integer) from anon;
revoke all on function public.description_sweep_batch(timestamptz, integer) from authenticated;
revoke all on function public.claim_description_run(integer) from public;
revoke all on function public.claim_description_run(integer) from anon;
revoke all on function public.claim_description_run(integer) from authenticated;
alter table public.description_runs enable row level security;
